{
  "interpretation": {
    "name": "TightenForkliftFastenersLine2AndReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 of line 2 with the shared nutrunner NR7, then return the tool to the crib and release the reservation so other lines are not blocked.",
    "constraints": [
      "Reserve NR7 before any use and release it at the end (E1, E6)",
      "NR7 must be transported to the station before configure-tool and tighten-fasteners (E3)",
      "transport-tool must be delegated to the Executor agvexecutor (E2)",
      "The tightening program must come from get-program, with no literal torque or tolerance values (E4)",
      "The tightening must be evaluated and recorded for traceability (E5)",
      "Every tool-using Step depends on reserve-tool so the lease is renewed (E6)"
    ],
    "preference": "Return the tool and release the reservation as early as possible so the other lines are not blocked.",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-f30-tightening-with-tool-return",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "return-and-verify",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten-bolts"],
            "dep": ["program", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-bolts",
            "service": "tighten-fasteners",
